local OFFSET = Vector3.new(0, 0.5, 180)
local function fromBlender(v) return Vector3.new(v[1], v[3], -v[2]) end
local function v3(v) return Vector3.new(v[1], v[2], v[3]) end

-- Capture all protected sources before any model or marker mutation.
local protected = {}
local function protect(path)
    local current = game
    for token in string.gmatch(path, "[^/]+") do
        current = current:FindFirstChild(token)
        assert(current, "Required Stage 3.1 object missing: " .. path)
    end
    assert(current:IsA("LuaSourceContainer"), "Expected script at " .. path)
    protected[current] = current.Source
    return current
end
local config = protect("ReplicatedStorage/HotelConfig")
protect("ServerScriptService/HotelBootstrap")
protect("StarterPlayer/StarterPlayerScripts/ClientMain")
for _, name in ipairs({"DataService", "DiamondService", "EggService", "RoomService", "BoutiqueService", "AmenityService", "PetModelFactory"}) do
    protect("ServerScriptService/Modules/" .. name)
end
assert(string.match(config.Source, "RoyalEggPrice%s*=%s*750"), "Expected original RoyalEggPrice = 750")
assert(string.match(config.Source, 'DataStoreName%s*=%s*"ERH_Stage3_TEST_v1"'), "DataStoreName differs from the original handoff; installation stopped for inspection")
assert(string.match(config.Source, "EnableLegacyReadMigration%s*=%s*false"), "Expected original migration disabled")

local maps = {}
for _, child in ipairs(WS:GetChildren()) do
    if child.Name == "RoyalHotelMap" then table.insert(maps, child) end
end
assert(#maps <= 1, "Multiple RoyalHotelMap objects; resolve the duplicate before installing")
local map = maps[1]
assert(not map or map:IsA("Folder") or map:IsA("Model"), "RoyalHotelMap must be a Folder or Model")
assert(not map or not map:FindFirstChild("ERH_FrontSlice"), "Front slice is already installed. Run its rollback before importing a replacement")

local importGroupCount = 0
for _, child in ipairs(WS:GetChildren()) do
    if child.Name == "ERH_ImportedMeshes" then importGroupCount += 1 end
end
assert(importGroupCount == 1, "Expected exactly one ERH_ImportedMeshes model directly under Workspace; resolve duplicate imports before installation")
local imported = WS:FindFirstChild("ERH_ImportedMeshes")
assert(imported and (imported:IsA("Model") or imported:IsA("Folder")), "Import the FBX files, group their MeshParts as Workspace.ERH_ImportedMeshes, then rerun")
local mapped, importedMeshCount = {}, 0
local function uploadedMeshId(mesh)
    local id = string.match(mesh.MeshId, "^rbxassetid://(%d+)$")
        or string.match(mesh.MeshId, "^https?://www%.roblox%.com/asset/%?id=(%d+)$")
    return id and tonumber(id) > 0
end
for _, descendant in ipairs(imported:GetDescendants()) do
    if descendant:IsA("LuaSourceContainer") then error("Imported art must contain no scripts") end
    if descendant:IsA("BasePart") and not descendant:IsA("MeshPart") then error("ERH_ImportedMeshes must contain only the delivered MeshParts, not old Parts or collision helpers") end
    if descendant:IsA("MeshPart") then importedMeshCount += 1 end
end
for _, chunk in ipairs(DATA.chunks) do
    local matches = {}
    for _, descendant in ipairs(imported:GetDescendants()) do
        if descendant.Name == chunk.name and descendant:IsA("MeshPart") then table.insert(matches, descendant) end
    end
    assert(#matches == 1, "Expected exactly one imported MeshPart named " .. chunk.name .. "; found " .. #matches)
    local mesh = matches[1]
    assert(mesh.MeshId ~= "" and mesh.MeshId ~= "rbxassetid://0" and uploadedMeshId(mesh), "Upload the real imported mesh for " .. chunk.name .. "; a valid nonzero Roblox mesh asset ID is required")
    mapped[mesh] = chunk
end
assert(importedMeshCount == #DATA.chunks, "Unexpected extra MeshParts in ERH_ImportedMeshes; import only the delivered chunks")

-- This is the original ensureTestMap body, staged detached from Workspace.
-- It is reproduced only for the original saved place, which has no permanent map.
local function materializeOriginalFallback()
	local map = Instance.new("Folder")
	map.Name = "RoyalHotelMap"

	local floor = Instance.new("Part")
	floor.Name = "TestFloor"
	floor.Size = Vector3.new(140, 1, 140)
	floor.Anchored = true
	floor.Position = Vector3.new(0, 0, 0)
	floor.Color = Color3.fromRGB(246, 231, 238)
	floor.Material = Enum.Material.Marble
	floor.Parent = map

	local lobby = Instance.new("Part")
	lobby.Name = "LobbySpawn"
	lobby.Anchored = true
	lobby.Transparency = 1
	lobby.CanCollide = false
	lobby.Position = Vector3.new(0, 4, 0)
	lobby.Parent = map

	for i, name in ipairs({"SpaSpawn","CafeSpawn","PoolSpawn","BallroomSpawn","NurserySpawn","BoutiqueSpawn"}) do
		local p = lobby:Clone()
		p.Name = name
		p.Position = Vector3.new(-35 + i*12, 4, -20)
		p.Parent = map
	end

	local diamondFolder = Instance.new("Folder")
	diamondFolder.Name = "DiamondSpawns"
	diamondFolder.Parent = map
	local placements = {
		{Vector3.new(0,1,8),"Pink","Lobby"},{Vector3.new(5,1,8),"Pink","Lobby"},{Vector3.new(-5,1,8),"Blue","Lobby"},{Vector3.new(9,1,8),"Purple","Lobby"},
		{Vector3.new(20,1,18),"Pink","Garden"},{Vector3.new(-18,1,22),"Blue","Garden"},{Vector3.new(26,1,-20),"Purple","Garden"},{Vector3.new(-28,1,-16),"Gold","Secret"}
	}
	for idx, info in ipairs(placements) do
		local s = Instance.new("Part")
		s.Name = string.format("Spawn_%02d", idx)
		s.Size = Vector3.new(1,1,1)
		s.Anchored = true
		s.Transparency = 1
		s.CanCollide = false
		s.Position = info[1]
		s:SetAttribute("DiamondType", info[2])
		s:SetAttribute("Area", info[3])
		s.Parent = diamondFolder
	end

	local roomsFolder = Instance.new("Folder")
	roomsFolder.Name = "Rooms"
	roomsFolder.Parent = map
	for i, wing in ipairs({"Princess","Mermaid","Fairy"}) do
		local model = Instance.new("Model")
		model.Name = wing .. "101"
		model:SetAttribute("Wing", wing)
		model:SetAttribute("RoomId", wing:sub(1,1) .. "101")
		model.Parent = roomsFolder
		local claimStand = Instance.new("Part")
		claimStand.Name = "ClaimPrompt"
		claimStand.Size = Vector3.new(1,2,1)
		claimStand.Anchored = true
		claimStand.Position = Vector3.new(-20 + i*12, 2, 24)
		claimStand.Parent = model
