local function record(object, name)
    local ref = Instance.new("ObjectValue")
    ref.Name = name
    ref.Value = object
    ref:SetAttribute("OriginalCFrame", object.CFrame)
    ref:SetAttribute("OriginalSize", object.Size)
    ref:SetAttribute("OriginalAnchored", object.Anchored)
    ref:SetAttribute("OriginalCanCollide", object.CanCollide)
    ref:SetAttribute("OriginalCanTouch", object.CanTouch)
    ref:SetAttribute("OriginalCanQuery", object.CanQuery)
    ref:SetAttribute("OriginalCastShadow", object.CastShadow)
    ref:SetAttribute("OriginalTransparency", object.Transparency)
    ref:SetAttribute("OriginalColor", object.Color)
    ref:SetAttribute("OriginalMaterial", object.Material.Name)
    ref.Parent = rollback
    return ref
end
